INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='couscous'),1,'A staple of North Africa, from the kingdom at the continent''s northwest corner.'),
((SELECT id FROM dishes WHERE slug='couscous'),2,'Berber cooks were making it by the 13th century; UNESCO listed it as shared heritage of Morocco, Algeria, Tunisia and Mauritania in 2020.'),
((SELECT id FROM dishes WHERE slug='couscous'),3,'It is the traditional Friday family meal across the Maghreb, and the box of the instant version is in half the pantries in Europe.'),
((SELECT id FROM dishes WHERE slug='couscous'),4,'Semolina is rubbed with water into tiny pellets, then steamed — never boiled — in a perforated pot set over the stew it will be served with.'),
((SELECT id FROM dishes WHERE slug='couscous'),5,'Tiny steamed pellets of semolina, fluffed up and piled under a spiced vegetable and chickpea stew — the Friday meal of North Africa.'),
((SELECT id FROM dishes WHERE slug='fufu'),1,'A staple of West Africa, especially the country on the Gulf of Guinea once called the Gold Coast.'),
((SELECT id FROM dishes WHERE slug='fufu'),2,'Pounding starchy roots into a smooth dough is one of the region''s oldest techniques, done in a tall wooden mortar with a long pestle.'),
((SELECT id FROM dishes WHERE slug='fufu'),3,'It went viral worldwide on TikTok, where the running joke is that newcomers keep chewing it instead of swallowing.'),
((SELECT id FROM dishes WHERE slug='fufu'),4,'Boiled cassava and plantain are pounded until stretchy and springy, rolled into a ball, and dipped into soup — you tear, dip, and swallow.'),
((SELECT id FROM dishes WHERE slug='fufu'),5,'A smooth, springy pounded ball of cassava and plantain, served in a bowl of West African soup and swallowed rather than chewed.'),
((SELECT id FROM dishes WHERE slug='milk-tart'),1,'A dessert from the country at the southern tip of Africa, the one with eleven official languages.'),
((SELECT id FROM dishes WHERE slug='milk-tart'),2,'Dutch settlers at the Cape adapted a 17th-century Netherlands custard tart, using far more dairy and far less egg.'),
((SELECT id FROM dishes WHERE slug='milk-tart'),3,'It has its own national day in February, and Afrikaans speakers know it by a one-word name ending in "-tert".'),
((SELECT id FROM dishes WHERE slug='milk-tart'),4,'A thin pastry shell is filled with a pale custard set with cornflour rather than baked hard, then chilled and dusted with cinnamon.'),
((SELECT id FROM dishes WHERE slug='milk-tart'),5,'A chilled South African tart of pale, delicate milk custard in a thin crust, with cinnamon dusted over the top.'),
((SELECT id FROM dishes WHERE slug='moroccan-mint-tea'),1,'A drink poured all day long in the country at Africa''s northwest corner.'),
((SELECT id FROM dishes WHERE slug='moroccan-mint-tea'),2,'British traders offloaded surplus gunpowder green tea onto North African ports in the 1800s; local cooks added a fistful of a garden herb and a lot of sugar.'),
((SELECT id FROM dishes WHERE slug='moroccan-mint-tea'),3,'Refusing a glass is a genuine insult — three rounds are traditional, and the host pours from high above the glass to raise a foam.'),
((SELECT id FROM dishes WHERE slug='moroccan-mint-tea'),4,'Green tea steeps with a huge bundle of fresh leaves and sugar in a silver pot, then is poured in a long stream from a great height into small glasses.'),
((SELECT id FROM dishes WHERE slug='moroccan-mint-tea'),5,'Sweet green tea steeped with a fistful of fresh mint and poured theatrically from high above small glasses — the drink of Moroccan hospitality.'),
((SELECT id FROM dishes WHERE slug='aloo-paratha'),1,'A breakfast from the wheat-growing north of a very large South Asian country.'),
((SELECT id FROM dishes WHERE slug='aloo-paratha'),2,'It is Punjabi farmhouse food, built to fuel a whole morning in the fields.'),
((SELECT id FROM dishes WHERE slug='aloo-paratha'),3,'Highway truck stops across northern India serve it all day with a slab of white butter melting on top, a bowl of yogurt and a mango pickle.'),
((SELECT id FROM dishes WHERE slug='aloo-paratha'),4,'Spiced mashed potato is sealed inside a wheat dough ball, rolled flat, and griddled with plenty of ghee.'),
((SELECT id FROM dishes WHERE slug='aloo-paratha'),5,'A stuffed, pan-fried Indian flatbread filled with spiced potato, served hot with butter, yogurt and pickle for breakfast.'),
((SELECT id FROM dishes WHERE slug='pani-puri'),1,'A street snack eaten all over a large South Asian country — under about six different regional names.'),
((SELECT id FROM dishes WHERE slug='pani-puri'),2,'It probably descends from an ancient snack of the Gangetic plains, and spread nationwide from there.'),
((SELECT id FROM dishes WHERE slug='pani-puri'),3,'The vendor hands them over one at a time and you must eat each in a single bite before it collapses; arguing over whose neighbourhood cart is best is a national sport.'),
((SELECT id FROM dishes WHERE slug='pani-puri'),4,'Hollow crisp spheres are cracked open, filled with potato and chickpea, then dunked in chilled tangy mint-tamarind water.'),
((SELECT id FROM dishes WHERE slug='pani-puri'),5,'Crisp hollow shells filled with spiced potato and dunked in cold tamarind-mint water, eaten whole in one go.'),
((SELECT id FROM dishes WHERE slug='vindaloo'),1,'From a small coastal state on the western side of South Asia.'),
((SELECT id FROM dishes WHERE slug='vindaloo'),2,'It started as Portuguese carne de vinha d''alhos — meat in wine and garlic — and Goan cooks swapped palm vinegar for the wine and piled in chilies.'),
((SELECT id FROM dishes WHERE slug='vindaloo'),3,'British curry houses turned its name into a byword for the hottest thing on the menu, which is a misunderstanding: the original is about sourness, not heat.'),
((SELECT id FROM dishes WHERE slug='vindaloo'),4,'Meat marinates in vinegar with a paste of dried red chilies, garlic and warm spices, then slow-cooks until the sauce goes dark and sharp.'),
((SELECT id FROM dishes WHERE slug='vindaloo'),5,'A dark, sour-hot Goan curry of pork marinated in vinegar, garlic and red chilies — infamous as the macho order at British takeaways.'),
((SELECT id FROM dishes WHERE slug='gulab-jamun'),1,'A sweet found at every celebration across the South Asian subcontinent.'),
((SELECT id FROM dishes WHERE slug='gulab-jamun'),2,'It arrived with Persian and Central Asian cooks in the Mughal courts, adapted from a fried dough soaked in syrup called luqmat al-qadi.'),
((SELECT id FROM dishes WHERE slug='gulab-jamun'),3,'No Indian wedding, Diwali box or restaurant buffet ends without a bowl of them, usually two to a serving, warm.'),
((SELECT id FROM dishes WHERE slug='gulab-jamun'),4,'Milk solids are kneaded into small dough balls, fried gently until deep brown, then soaked in cardamom-and-rose sugar syrup.'),
((SELECT id FROM dishes WHERE slug='gulab-jamun'),5,'Warm, spongy deep-fried milk-solid balls soaked through with rose-and-cardamom syrup — the default Indian restaurant dessert.'),
((SELECT id FROM dishes WHERE slug='kulfi'),1,'A frozen sweet from the subcontinent, sold from carts on hot afternoons.'),
((SELECT id FROM dishes WHERE slug='kulfi'),2,'Mughal cooks made it in the 16th century, freezing it in metal cones packed in ice hauled down from the Himalayas with saltpetre.'),
((SELECT id FROM dishes WHERE slug='kulfi'),3,'Vendors still sell it from a cloth-wrapped clay pot, sliding the cones out and cutting them onto a leaf plate.'),
((SELECT id FROM dishes WHERE slug='kulfi'),4,'Milk is boiled down for hours until thick and faintly caramelised, flavoured with cardamom and pistachio, then frozen solid in cone moulds without any churning.'),
((SELECT id FROM dishes WHERE slug='kulfi'),5,'A dense, unchurned Indian frozen dessert of reduced milk scented with cardamom, saffron and pistachio, served on a stick.'),
((SELECT id FROM dishes WHERE slug='mango-lassi'),1,'A cold drink from the northern plains of South Asia.'),
((SELECT id FROM dishes WHERE slug='mango-lassi'),2,'The yogurt drink underneath it goes back some three thousand years in Punjab; the fruit version is a much more recent, restaurant-friendly twist.'),
((SELECT id FROM dishes WHERE slug='mango-lassi'),3,'It is what people order to put out the fire after an over-ambitious curry, and the default drink on Indian restaurant menus across the West.'),
((SELECT id FROM dishes WHERE slug='mango-lassi'),4,'Thick yogurt is blended with ripe tropical fruit pulp, milk and sugar with a pinch of cardamom, then poured over ice.'),
((SELECT id FROM dishes WHERE slug='mango-lassi'),5,'A thick, sweet, chilled yogurt drink blended with ripe tropical fruit — the standard cooler alongside a hot curry.'),
((SELECT id FROM dishes WHERE slug='masala-chai'),1,'A hot drink poured out by the millions every day across South Asia.'),
((SELECT id FROM dishes WHERE slug='masala-chai'),2,'The British planted the leaf in Assam in the 1800s to break China''s monopoly; Indian vendors stretched the expensive stuff with milk, sugar and spice.'),
((SELECT id FROM dishes WHERE slug='masala-chai'),3,'Railway platform vendors call it out all night, serving it in tiny glasses or throwaway clay cups you smash when you''re done — and Western coffee chains sell a sweetened latte version.'),
((SELECT id FROM dishes WHERE slug='masala-chai'),4,'Black tea, water, milk and sugar are boiled together with crushed ginger and whole warm spices, then strained from a height.'),
((SELECT id FROM dishes WHERE slug='masala-chai'),5,'Strong black tea boiled with milk, sugar, ginger and warm spices, strained and drunk scalding hot from a small glass.'),
((SELECT id FROM dishes WHERE slug='aloo-gobi'),1,'A homely vegetable dish from the north of a very large South Asian country.'),
((SELECT id FROM dishes WHERE slug='aloo-gobi'),2,'It is Punjabi household cooking — two cheap, sturdy vegetables that hold up to a long dry fry.'),
((SELECT id FROM dishes WHERE slug='aloo-gobi'),3,'It is the reliable vegetarian order on every Indian restaurant menu in Britain, and gets its own running joke in the film Bend It Like Beckham.'),
((SELECT id FROM dishes WHERE slug='aloo-gobi'),4,'Potato and cauliflower florets are dry-fried with turmeric, cumin and ginger until the edges catch and everything turns golden — no gravy.'),
((SELECT id FROM dishes WHERE slug='aloo-gobi'),5,'A dry, golden turmeric-stained Indian curry of potato and cauliflower, finished with fresh coriander.'),
((SELECT id FROM dishes WHERE slug='onion-bhaji'),1,'A fried starter from a very large South Asian country.'),
((SELECT id FROM dishes WHERE slug='onion-bhaji'),2,'Fritters of this kind are ancient street food across the subcontinent; the round, tightly packed restaurant version was standardised by British curry houses.'),
((SELECT id FROM dishes WHERE slug='onion-bhaji'),3,'It is one third of the standard British curry-house starter platter, alongside a samosa and a poppadom.'),
((SELECT id FROM dishes WHERE slug='onion-bhaji'),4,'Sliced onion is bound in a spiced chickpea-flour batter and deep-fried into a craggy, tangled nest.'),
((SELECT id FROM dishes WHERE slug='onion-bhaji'),5,'A craggy deep-fried nest of sliced onion in spiced chickpea-flour batter, served with mint chutney.'),
((SELECT id FROM dishes WHERE slug='raita'),1,'A cooling side from a very large South Asian country.'),
((SELECT id FROM dishes WHERE slug='raita'),2,'Yogurt has been used to temper spice on the subcontinent for millennia; recipes for this appear in Mughal-era court cookbooks.'),
((SELECT id FROM dishes WHERE slug='raita'),3,'It is the thing every Indian restaurant brings out when somebody at the table has badly overestimated their tolerance for chili.'),
((SELECT id FROM dishes WHERE slug='raita'),4,'Whisked yogurt is thinned with a little water and stirred with grated cucumber, roasted cumin and fresh herbs, then served cold.'),
((SELECT id FROM dishes WHERE slug='raita'),5,'A cold whisked-yogurt side with grated cucumber, roasted cumin and mint, served to put out the fire of a hot curry.'),
((SELECT id FROM dishes WHERE slug='paneer-tikka'),1,'A skewered starter from the north of a very large South Asian country.'),
((SELECT id FROM dishes WHERE slug='paneer-tikka'),2,'It is the meatless answer to the Punjabi clay-oven grill, developed for the vast vegetarian half of the country.'),
((SELECT id FROM dishes WHERE slug='paneer-tikka'),3,'It is the fixture of every Indian restaurant starter list and every Delhi wedding buffet, arriving on a sizzling iron platter.'),
((SELECT id FROM dishes WHERE slug='paneer-tikka'),4,'Cubes of firm fresh cheese marinate in spiced yogurt with peppers and onion, then char on skewers in a searing clay oven.'),
((SELECT id FROM dishes WHERE slug='paneer-tikka'),5,'Charred skewers of firm Indian cheese marinated in spiced yogurt, grilled with peppers and onion and served with a lemon wedge.'),
((SELECT id FROM dishes WHERE slug='soto-ayam'),1,'A soup from the world''s largest archipelago, in Southeast Asia.'),
((SELECT id FROM dishes WHERE slug='soto-ayam'),2,'Every region of Java has its own version — Lamongan, Kudus, Madura — and the dish travelled with Javanese migration to Malaysia and Suriname.'),
((SELECT id FROM dishes WHERE slug='soto-ayam'),3,'It is the standard comfort food and hangover cure across Indonesia, sold from carts and warungs at all hours with a lime wedge and prawn crackers.'),
((SELECT id FROM dishes WHERE slug='soto-ayam'),4,'Chicken simmers with lemongrass, galangal and turmeric until the broth turns bright gold, then is shredded over noodles, bean sprouts and boiled egg.'),
((SELECT id FROM dishes WHERE slug='soto-ayam'),5,'A golden turmeric chicken broth over noodles with shredded chicken, bean sprouts and boiled egg, brightened with lime and fried shallots.'),
((SELECT id FROM dishes WHERE slug='nasi-lemak'),1,'The national breakfast of a Southeast Asian country split between a peninsula and part of Borneo.'),
((SELECT id FROM dishes WHERE slug='nasi-lemak'),2,'It was Malay farmers'' field food, first written down in a 1909 book about Malay life, and traditionally wrapped in a banana-leaf parcel.'),
((SELECT id FROM dishes WHERE slug='nasi-lemak'),3,'Malaysians will argue for hours over whose stall makes it best; it is served on the national airline and at 3am roadside stalls alike.'),
((SELECT id FROM dishes WHERE slug='nasi-lemak'),4,'Rice is steamed in coconut milk with a knotted fragrant leaf, then plated with sweet-hot sambal, crisp fried anchovies, peanuts, cucumber and egg.'),
((SELECT id FROM dishes WHERE slug='nasi-lemak'),5,'Coconut-scented rice in a banana leaf with fiery sambal, fried anchovies, peanuts, cucumber and a boiled egg — Malaysia''s breakfast.'),
((SELECT id FROM dishes WHERE slug='chili-crab'),1,'From a small island city-state at the bottom of the Malay Peninsula.'),
((SELECT id FROM dishes WHERE slug='chili-crab'),2,'A woman named Cher Yam Tian started selling it from a pushcart on the East Coast in 1956, at first with nothing but bottled tomato sauce.'),
((SELECT id FROM dishes WHERE slug='chili-crab'),3,'It is the dish the national tourism board leads with, and CNN once put it on a list of the world''s fifty best foods.'),
((SELECT id FROM dishes WHERE slug='chili-crab'),4,'Whole shellfish are stir-fried in a thick sweet-savoury tomato gravy ribboned with beaten egg, and you mop the sauce up with fried buns.'),
((SELECT id FROM dishes WHERE slug='chili-crab'),5,'Whole shellfish in a sticky, egg-swirled sweet-and-spicy tomato gravy, eaten with your hands and steamed buns for the sauce.'),
((SELECT id FROM dishes WHERE slug='halo-halo'),1,'A dessert from an archipelago of over seven thousand islands in Southeast Asia.'),
((SELECT id FROM dishes WHERE slug='halo-halo'),2,'It grew out of Japanese kakigori brought over by pre-war migrants, then got piled high with local sweetened preserves.'),
((SELECT id FROM dishes WHERE slug='halo-halo'),3,'Anthony Bourdain was a public champion of it, and its name literally means "mix-mix" — which is also the instruction.'),
((SELECT id FROM dishes WHERE slug='halo-halo'),4,'Shaved ice and evaporated milk go over a tall glass layered with sweet beans, jellies, preserved fruit and purple yam, topped with ice cream.'),
((SELECT id FROM dishes WHERE slug='halo-halo'),5,'A tall glass of shaved ice and evaporated milk over sweet beans, jellies and preserved fruit, crowned with ice cream — stir it all together before eating.'),
((SELECT id FROM dishes WHERE slug='fresh-spring-rolls'),1,'A cold starter from a long, narrow country on the eastern edge of Southeast Asia.'),
((SELECT id FROM dishes WHERE slug='fresh-spring-rolls'),2,'They are the uncooked southern Vietnamese cousin of the fried rolls found all over East and Southeast Asia.'),
((SELECT id FROM dishes WHERE slug='fresh-spring-rolls'),3,'They are the health-conscious order on every Vietnamese menu in the West, and are often called summer rolls to tell them apart from the fried kind.'),
((SELECT id FROM dishes WHERE slug='fresh-spring-rolls'),4,'Translucent rice paper is dipped in water until pliable, then wrapped around herbs, noodles and shellfish — never cooked — and dipped in peanut sauce.'),
((SELECT id FROM dishes WHERE slug='fresh-spring-rolls'),5,'Translucent uncooked rice-paper rolls packed with shrimp, noodles and fresh herbs, served cold with peanut dipping sauce.'),
((SELECT id FROM dishes WHERE slug='pad-see-ew'),1,'A noodle dish from a Southeast Asian kingdom that was never colonised.'),
((SELECT id FROM dishes WHERE slug='pad-see-ew'),2,'It came to Thailand with Chinese immigrants — the name means "fried with soy sauce" — and it is a close relative of Cantonese beef chow fun.'),
((SELECT id FROM dishes WHERE slug='pad-see-ew'),3,'It is the second thing everyone orders at a Thai restaurant after the more famous tamarind noodle dish next to it on the menu.'),
((SELECT id FROM dishes WHERE slug='pad-see-ew'),4,'Wide flat rice noodles are charred hard in a screaming-hot wok with dark sweet soy, egg and Chinese broccoli until they smoke.'),
((SELECT id FROM dishes WHERE slug='pad-see-ew'),5,'Wide flat rice noodles charred in a wok with dark sweet soy sauce, egg and Chinese broccoli — Thailand''s smoky, savoury noodle plate.'),
((SELECT id FROM dishes WHERE slug='thai-iced-tea'),1,'A cold drink from a Southeast Asian kingdom famous for its street food.'),
((SELECT id FROM dishes WHERE slug='thai-iced-tea'),2,'It came out of the mid-20th century, when strong spiced black tea met imported tinned milk in Bangkok.'),
((SELECT id FROM dishes WHERE slug='thai-iced-tea'),3,'Its startling traffic-cone orange colour — from food dye in the tea mix — is the giveaway on any takeaway menu in the West.'),
((SELECT id FROM dishes WHERE slug='thai-iced-tea'),4,'Strong spiced black tea is brewed dark, sweetened hard with condensed milk, poured over ice and floated with evaporated milk.'),
((SELECT id FROM dishes WHERE slug='thai-iced-tea'),5,'A bright orange, very sweet iced spiced tea layered with condensed and evaporated milk — the standard drink with a Thai takeaway.'),
((SELECT id FROM dishes WHERE slug='mango-sticky-rice'),1,'A hot-season dessert from a Southeast Asian kingdom known for its beaches and street food.'),
