((SELECT id FROM dishes WHERE slug='kimbap'),4,'Seasoned rice and strips of vegetables, egg and pickled radish are rolled up in a sheet of dried seaweed and cut into rounds.'),
((SELECT id FROM dishes WHERE slug='kimbap'),5,'Cold seaweed-and-rice rolls filled with strips of vegetables and egg, sliced into coins for a Korean picnic lunch.'),
