((SELECT id FROM dishes WHERE slug='gravlax'),4,'Raw fillets are cured for days under a weighted blanket of salt, sugar and dill — never cooked, and never smoked.'),
((SELECT id FROM dishes WHERE slug='gravlax'),5,'Salt-and-sugar cured raw salmon packed in dill, sliced thin and served cold with sweet mustard sauce.'),
